const cfg = $('Variaveis do sistema').item.json;
const headers = { 'x-whatsapp-token': cfg.apiToken };
const i=this.getInputData()[0].json; const body={telefone:cfg.Telefone,nome:cfg.NomeWpp,profissionalId:i.profissionalId,servicoId:i.servicoId,data:i.dataIso}; const r=await $helpers.httpRequest({method:'POST',url:`${cfg.backendUrl}/whatsapp/agenda/agendamentos?tenantId=${cfg.tenantId}`,headers,body}); return `Agendamento ${r.id} criado com sucesso.`;

